      "bugungi qisqa xulosa": { ru: "\u043A\u0440\u0430\u0442\u043A\u0430\u044F \u0441\u0432\u043E\u0434\u043A\u0430 \u043D\u0430 \u0441\u0435\u0433\u043E\u0434\u043D\u044F", en: "today\u2019s quick summary" },
      "obyektlar ro\u2018yxati": { ru: "\u0441\u043F\u0438\u0441\u043E\u043A \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432", en: "list of objects" },
      "Jarvis ga savol (tokenlar sarflanadi)": { ru: "\u0432\u043E\u043F\u0440\u043E\u0441 Jarvis (\u0442\u0440\u0430\u0442\u044F\u0442\u0441\u044F \u0442\u043E\u043A\u0435\u043D\u044B)", en: "ask Jarvis (tokens are spent)" },
