      "Hozir sizning qaroringiz kutilmayapti yoki ruxsatingiz yo\u2018q.": { ru: "\u0421\u0435\u0439\u0447\u0430\u0441 \u0432\u0430\u0448\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0438\u043B\u0438 \u043D\u0435\u0442 \u043F\u0440\u0430\u0432.", en: "Your decision is not pending right now, or you lack permission." },
      "Server xatosi. Mini App da urinib ko\u2018ring.": { ru: "\u041E\u0448\u0438\u0431\u043A\u0430 \u0441\u0435\u0440\u0432\u0435\u0440\u0430. \u041F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0432 Mini App.", en: "Server error. Try in the Mini App." },
      Tasdiqlandi: { ru: "\u0421\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u043E", en: "Approved" },
      Bajarilmadi: { ru: "\u041D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043E", en: "Not done" },
      Tasdiqlar: { ru: "\u0421\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u0438\u044F", en: "Approvals" },
      Fakt: { ru: "\u0424\u0430\u043A\u0442", en: "Fact" },
      "F-2 reestri": { ru: "\u0420\u0435\u0435\u0441\u0442\u0440 \u0424-2", en: "F-2 register" },
      "Ko\u2018rish": { ru: "\u041E\u0442\u043A\u0440\u044B\u0442\u044C", en: "View" },
      "Foto-dalil": { ru: "\u0424\u043E\u0442\u043E-\u0434\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430", en: "Photo evidence" },
      "Faktga biriktirish": { ru: "\u041F\u0440\u0438\u0432\u044F\u0437\u0430\u0442\u044C \u043A \u0444\u0430\u043A\u0442\u0443", en: "Attach to fact" },
