var telegram_kirish_default;
var init_telegram_kirish = __esm({
  "../src/i18n/lugat/qism/telegram-kirish.json"() {
    telegram_kirish_default = {
      "Saytdagi kirish so\u2018rovi. Moslik raqami: {belgi}. Saytda ham aynan shu raqam ko\u2018rinib tursa, pastdagi tugma orqali O\u2018ZINGIZNING telefon raqamingizni yuboring. Ko\u2018rinmasa yoki bu so\u2018rovni siz boshlamagan bo\u2018lsangiz \u2014 hech narsa yubormang.": {
        ru: "\u0417\u0430\u043F\u0440\u043E\u0441 \u043D\u0430 \u0432\u0445\u043E\u0434 \u0441 \u0441\u0430\u0439\u0442\u0430. \u041A\u043E\u0434 \u0441\u0432\u0435\u0440\u043A\u0438: {belgi}. \u0415\u0441\u043B\u0438 \u043D\u0430 \u0441\u0430\u0439\u0442\u0435 \u0432\u0438\u0434\u0435\u043D \u044D\u0442\u043E\u0442 \u0436\u0435 \u043A\u043E\u0434, \u043E\u0442\u043F\u0440\u0430\u0432\u044C\u0442\u0435 \u0421\u0412\u041E\u0419 \u043D\u043E\u043C\u0435\u0440 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430 \u043A\u043D\u043E\u043F\u043A\u043E\u0439 \u043D\u0438\u0436\u0435. \u0415\u0441\u043B\u0438 \u043A\u043E\u0434 \u043D\u0435 \u0441\u043E\u0432\u043F\u0430\u0434\u0430\u0435\u0442 \u0438\u043B\u0438 \u0432\u044B \u043D\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u043B\u0438 \u044D\u0442\u043E\u0442 \u0437\u0430\u043F\u0440\u043E\u0441 \u2014 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0439\u0442\u0435.",
        en: "Sign-in request from the website. Match code: {belgi}. If the website shows the same code, share YOUR OWN phone number with the button below. If it does not match, or you did not start this request, send nothing."
      },
      "Raqamimni yuborish": { ru: "\u041E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u043C\u043E\u0439 \u043D\u043E\u043C\u0435\u0440", en: "Share my number" },
      "Raqam tasdiqlandi. Saytga qayting \u2014 kirish avtomatik tugaydi.": { ru: "\u041D\u043E\u043C\u0435\u0440 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043D. \u0412\u0435\u0440\u043D\u0438\u0442\u0435\u0441\u044C \u043D\u0430 \u0441\u0430\u0439\u0442 \u2014 \u0432\u0445\u043E\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.", en: "Number confirmed. Go back to the website \u2014 sign-in will finish automatically." },
      "Faqat o\u2018zingizning raqamingizni yuboring (pastdagi tugma orqali). Boshqa odamning kontakti qabul qilinmaydi.": { ru: "\u041E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0439\u0442\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u0432\u043E\u0439 \u043D\u043E\u043C\u0435\u0440 (\u043A\u043D\u043E\u043F\u043A\u043E\u0439 \u043D\u0438\u0436\u0435). \u041A\u043E\u043D\u0442\u0430\u043A\u0442 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430 \u043D\u0435 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F.", en: "Send only your own number (with the button below). Someone else's contact is not accepted." },
      "Hozircha faqat O\u2018zbekiston (+998) raqamlari qabul qilinadi. Saytdan qaytadan boshlang.": { ru: "\u041F\u043E\u043A\u0430 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u043E\u043C\u0435\u0440\u0430 \u0423\u0437\u0431\u0435\u043A\u0438\u0441\u0442\u0430\u043D\u0430 (+998). \u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0437\u0430\u043D\u043E\u0432\u043E \u043D\u0430 \u0441\u0430\u0439\u0442\u0435.", en: "Only Uzbekistan (+998) numbers are accepted for now. Start again on the website." },
      "So\u2018rov topilmadi yoki muddati tugagan (5 daqiqa). Saytdan qaytadan boshlang.": { ru: "\u0417\u0430\u043F\u0440\u043E\u0441 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D \u0438\u043B\u0438 \u0438\u0441\u0442\u0451\u043A (5 \u043C\u0438\u043D\u0443\u0442). \u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0437\u0430\u043D\u043E\u0432\u043E \u043D\u0430 \u0441\u0430\u0439\u0442\u0435.", en: "Request not found or expired (5 minutes). Start again on the website." },
      "Telegram orqali kirish hozircha yoqilmagan.": { ru: "\u0412\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 Telegram \u043F\u043E\u043A\u0430 \u043D\u0435 \u0432\u043A\u043B\u044E\u0447\u0451\u043D.", en: "Sign-in via Telegram is not enabled yet." }
    };
  }
});

