      "Bekor qilindi": "\u041E\u0442\u043C\u0435\u043D\u0435\u043D\u043E",
      "Bepul sinov": "\u0411\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u0430\u044F \u043F\u0440\u043E\u0431\u0430",
      "PTO Start": "PTO Start",
      "PTO Pro": "PTO Pro",
      "PTO Expert": "PTO Expert",
      "500 token": "500 \u0442\u043E\u043A\u0435\u043D\u043E\u0432",
