      "RES ga o\u2018tish": "\u041F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0420\u0415\u0421",
      "o\u2018rta ishonch": "\u0441\u0440\u0435\u0434\u043D\u044F\u044F \u0443\u0432\u0435\u0440\u0435\u043D\u043D\u043E\u0441\u0442\u044C",
      "past ishonch": "\u043D\u0438\u0437\u043A\u0430\u044F \u0443\u0432\u0435\u0440\u0435\u043D\u043D\u043E\u0441\u0442\u044C",
      "Narx nomzodi": "\u041A\u0430\u043D\u0434\u0438\u0434\u0430\u0442 \u0446\u0435\u043D\u044B",
      "\u2014 nomzodni tanlang \u2014": "\u2014 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u043D\u0434\u0438\u0434\u0430\u0442\u0430 \u2014",
      "Kompaniya nakrutka sozlamasi": "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u043D\u0430\u043A\u0440\u0443\u0442\u043E\u043A \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0438",
      "Tizim standarti (kompaniya sozlamasi o\u2018qilmadi)": "\u0421\u0442\u0430\u043D\u0434\u0430\u0440\u0442 \u0441\u0438\u0441\u0442\u0435\u043C\u044B (\u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0438 \u043D\u0435 \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u0430)",
      "Foiz 0 dan 100 gacha bo\u2018lishi kerak: {k}": "\u041F\u0440\u043E\u0446\u0435\u043D\u0442 \u0434\u043E\u043B\u0436\u0435\u043D \u0431\u044B\u0442\u044C \u043E\u0442 0 \u0434\u043E 100: {k}",
      Operator: "\u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440",
      "Stavkalar tasdiqlandi \u2014 RES ostida nakrutka kaskadi chiqadi.": "\u0421\u0442\u0430\u0432\u043A\u0438 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u044B \u2014 \u043F\u043E\u0434 \u0420\u0415\u0421 \u0431\u0443\u0434\u0435\u0442 \u043A\u0430\u0441\u043A\u0430\u0434 \u043D\u0430\u043A\u0440\u0443\u0442\u043E\u043A.",
      "Foiz stavkalari": "\u041F\u0440\u043E\u0446\u0435\u043D\u0442\u043D\u044B\u0435 \u0441\u0442\u0430\u0432\u043A\u0438",
      "Foiz stavkalari (nakrutka)": "\u041F\u0440\u043E\u0446\u0435\u043D\u0442\u043D\u044B\u0435 \u0441\u0442\u0430\u0432\u043A\u0438 (\u043D\u0430\u043A\u0440\u0443\u0442\u043A\u0438)",
      Tasdiqlangan: "\u0423\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u043E",
